"""Topic taxonomy and reviewed English image lookup aids, independent of grammar."""
CATEGORIES=['Family and friends','People and jobs','Body and senses','Health and hygiene','Feelings and personality','Food and ingredients','Meals and cooking','Home and household','Clothing and accessories','Personal things and technology','School and learning','Language and numbers','Daily actions and routines','Sports and movement','Games, arts and hobbies','Animals and living things','Nature and weather','Places and travel','Time and position','Conversation and describing']
def classify(w,force=False):
    if w.get('taxonomy_version')==2 or (w['category'] in CATEGORIES and not force and w['category'] not in {'School and learning','Conversation and describing'}):return w['category']
    key=w['english'].lower();topic=w['topic'].lower();old=w['category']
    jobs=set('job profession teacher doctor nurse dentist driver farmer artist singer worker police manager boss pilot sailor scientist actor actress baker butcher mechanic cleaner librarian firefighter shopkeeper cashier hairdresser plumber carpenter electrician builder waiter waitress receptionist photographer poet author musician vet optician coach steward stewardess colleague customer tourist visitor passenger owner leader officer journalist writer employee secretary lawyer editor engineer volunteer helper guide'.split())
    family=set('mother father brother sister grandmother grandfather aunt uncle cousin baby child friend family parent boy girl man woman person people adult teenager daughter son husband wife neighbor guest toddler classmate teammate stranger twin grandchild granddaughter grandson nephew niece relationship friendship marriage'.split())
    health=set('health medicine hospital pain illness injury wound fever cough thermometer bandage plaster crutch wheelchair ambulance sneeze hiccup bruise bump scratch rash allergy headache stomachache toothache earache sprain hygiene sunscreen rest treatment disease cancer sick ill healthy unhealthy fit unfit first aid handwashing cold flu hearing eyesight breathing heartbeat pulse'.split())
    feelings=set('happy sad angry tired hungry thirsty afraid upset fear joy pleasure happiness sadness excitement worry surprise pride shyness boredom patience kindness anger courage disappointment comfort relief emotion curious thoughtful helpful cheerful miserable nervous anxious worried excited surprised bored sleepy awake alert calm relaxed lonely proud embarrassed interested interesting brave shy generous selfish polite rude honest dishonest patient impatient gentle sensible careless tidy neat confident uncertain sure unsure grateful friendly kind sorry love hate like wish hope imagine dream memory concentration attention'.split())
    meals=set('breakfast lunch dinner meal snack dessert picnic recipe ingredient portion leftover cooking soup sandwich pizza cake stew sauce gravy butter omelette pasta noodle noodle lasagna couscous porridge cereal oatmeal toast cracker pancake waffle dough pastry muffin cupcake bun croissant pita mayonnaise ketchup mustard jam marmalade custard cream pudding cheesecake popcorn lemonade smoothie milkshake cocoa jelly ice cream hot chocolate tap water mineral water juice drink tea coffee delicious tasty flavour aroma ripe unripe bitter salty spicy chewy crunchy raw cooked boiled fried baked grilled roasted sliced chopped grated bowl dish plate cup mug kettle spoon fork knife pan pot colander sieve spatula whisk ladle grater napkin saucer'.split())
    technology=set('phone telephone computer screen camera keyboard microphone earphone headphone printer charger battery cable plug socket tablet internet browser website email password username app software device document file folder program television radio video recorder remote control'.split())
    sports=set('ball football tennis basketball volleyball badminton cricket baseball softball hockey rugby handball netball table tennis golf squash athletics gymnastics yoga karate judo boxing wrestling archery skating skiing surfing sailing rowing canoeing kayaking hiking jogging diving cycling swimming sports sport bicycle bike trampoline racket bat goal goalkeeper referee opponent spectator medal trophy tournament championship score race player coach running skating skate ski swim run jump climb exercise'.split())
    animals=set('cat dog bird horse cow sheep goat pig rabbit duck hen lion tiger elephant giraffe monkey bear wolf fox mouse rat snake frog turtle butterfly bee ant spider insect animal pet tail wing feather puppy kitten foal calf lamb duckling chick gosling cub fawn penguin eagle owl parrot pigeon sparrow robin swallow seagull flamingo ostrich peacock turkey goose swan crow magpie woodpecker dolphin whale shark seal walrus octopus squid crab lobster shrimp prawn starfish jellyfish seahorse salmon tuna trout cod sardine goldfish lizard crocodile alligator chameleon gecko tortoise snail slug worm caterpillar beetle ladybird dragonfly mosquito moth wasp grasshopper scorpion hedgehog squirrel badger otter raccoon kangaroo koala panda camel donkey zebra hippo rhinoceros deer moose reindeer antelope cheetah leopard buffalo bison gorilla chimpanzee orangutan meerkat hamster gerbil paw hoof claw whisker beak snout mane fur fin gill nest'.split())
    timepos=set('monday tuesday wednesday thursday friday saturday sunday january february march april may june july august september october november december today tomorrow yesterday now later soon morning afternoon evening night day week month year time hour minute second first last next before after early late always never often sometimes usually rarely daily weekly monthly yearly once twice finally recently currently eventually immediately suddenly tonight then already yet still ago future past present position direction left right above below behind between inside outside under over beside near far here there anywhere everywhere somewhere nowhere upstairs downstairs indoors outdoors along across around throughout onto into towards beyond within opposite north south east west'.split())
    language=set('word letter name question answer language grammar noun verb sentence spelling paragraph alphabet vowel consonant syllable rhyme handwriting punctuation comma colon apostrophe quotation title heading subtitle chapter reading writing dictation dictionary number digit fraction decimal percent sum half quarter'.split())
    body=set('head face eye ear nose mouth tooth tongue hair hand arm leg foot finger shoulder knee neck back skin stomach heart body blood bone muscle lip chest cheek throat brain ankle elbow wrist thumb palm fingernail toenail chin eyebrow eyelash forehead cheekbone heel hip waist spine rib lung kidney liver skeleton breath voice eyesight hearing breathing heartbeat pulse'.split())
    if force:
        if key in body:return CATEGORIES[2]
        if key in feelings:return CATEGORIES[4]
        if w.get('pos')=='number' or key in language:return CATEGORIES[11]
        if key in timepos:return CATEGORIES[18]
        if old=='Conversation and describing' and w.get('pos')=='verb':return CATEGORIES[12]
    if old in CATEGORIES and old not in {'School and learning','Conversation and describing'}:return old
    if w.get('pos')=='number' or key in language or 'number' in topic: return CATEGORIES[11]
    if key in timepos: return CATEGORIES[18]
    if old=='Family and people': return CATEGORIES[1] if key in jobs or key not in family else CATEGORIES[0]
    if old=='Body, health and feelings': return CATEGORIES[4] if key in feelings else (CATEGORIES[2] if key in body else CATEGORIES[3])
    if old=='Food and drink': return CATEGORIES[6] if key in meals else CATEGORIES[5]
    if old=='Home and daily life': return CATEGORIES[9] if key in technology else CATEGORIES[7]
    if old=='Clothes and personal things': return CATEGORIES[9] if key in technology or key in {'watch','clock','bag','gift','present','wallet','toothbrush','toothpaste','soap','tissue','perfume','lotion','shampoo','conditioner','comb','brush'} else CATEGORIES[8]
    if old=='School and learning': return CATEGORIES[9] if key in technology else CATEGORIES[10]
    if old=='Play, sports and hobbies': return CATEGORIES[13] if key in sports else CATEGORIES[14]
    if old=='Animals, nature and weather': return CATEGORIES[15] if key in animals else CATEGORIES[16]
    if old=='Places, travel and holidays': return CATEGORIES[17]
    if key in feelings:return CATEGORIES[4]
    if w.get('pos')=='verb' or 'action' in topic:return CATEGORIES[12]
    return CATEGORIES[19]
